contracts/arena/ArenaEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./ArenaTreasury.sol";

/**
 * @title  ArenaEscrow
 *
 * @notice Replaces the old off-chain wager ledger (Postgres AgentWallet /
 *         EscrowRecord) with a real on-chain escrow for 1v1 AI Arena
 *         battles. Player stakes are pulled via `transferFrom` — each
 *         player approves this contract once from their own wallet, then
 *         every subsequent stake/settle call is submitted and gas-paid by
 *         the backend relayer, so players never need native 0G tokens.
 *
 * Flow (matches the ARENA 0G blueprint):
 *   createMatch(playerA stakes)  -> MatchCreated
 *   joinMatch(playerB stakes)    -> MatchJoined   (pool = 2x stake)
 *   startMatch()                 -> MatchStarted   (backend now runs the AI battle off-chain)
 *   settleMatch(winner)          -> MatchSettled + CommissionCollected
 *
 * Example: stake 5 + stake 5 = pool 10; winner gets 9 (90%); treasury gets 1 (10%).
 *
 * @dev    The backend never manually transfers player rewards — every
 *         payout here is a contract-executed ERC20 transfer, and the
 *         backend's only privilege is *triggering* these state transitions
 *         (RELAYER_ROLE), not moving funds directly.
 */
contract ArenaEscrow is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");

    enum MatchState { NONE, CREATED, JOINED, STARTED, SETTLED, CANCELLED }

    struct Match {
        address playerA;
        address playerB;
        uint256 stakeAmount;
        MatchState state;
    }

    IERC20 public immutable arenaToken;
    ArenaTreasury public immutable treasury;

    /// @notice Commission taken from the pool at settlement, in basis points. 1000 = 10%.
    uint256 public commissionBps = 1000;
    uint256 public constant MAX_COMMISSION_BPS = 2000; // hard cap: 20%

    mapping(bytes32 => Match) public matches;

    event MatchCreated(bytes32 indexed matchId, address indexed playerA, uint256 stakeAmount);
    event MatchJoined(bytes32 indexed matchId, address indexed playerB, uint256 pool);
    event MatchStarted(bytes32 indexed matchId);
    event MatchSettled(bytes32 indexed matchId, address indexed winner, uint256 payout, uint256 commission);
    event MatchCancelled(bytes32 indexed matchId);
    event CommissionCollected(bytes32 indexed matchId, uint256 amount);
    event CommissionBpsUpdated(uint256 newBps);

    constructor(address admin, address arenaTokenAddress, address treasuryAddress) {
        require(admin != address(0), "zero admin");
        require(arenaTokenAddress != address(0), "zero token");
        require(treasuryAddress != address(0), "zero treasury");
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        arenaToken = IERC20(arenaTokenAddress);
        treasury = ArenaTreasury(treasuryAddress);
    }

    /// @notice Player A stakes and opens a match. `matchId` is caller-chosen (e.g. keccak256 of an off-chain battle UUID) and must be unused.
    function createMatch(bytes32 matchId, address playerA, uint256 stakeAmount) external onlyRole(RELAYER_ROLE) whenNotPaused nonReentrant {
        require(matches[matchId].state == MatchState.NONE, "match exists");
        require(playerA != address(0), "zero player");
        require(stakeAmount > 0, "zero stake");

        matches[matchId] = Match({ playerA: playerA, playerB: address(0), stakeAmount: stakeAmount, state: MatchState.CREATED });
        arenaToken.safeTransferFrom(playerA, address(this), stakeAmount);

        emit MatchCreated(matchId, playerA, stakeAmount);
    }

    /// @notice Player B joins with an equal stake, forming the pool.
    function joinMatch(bytes32 matchId, address playerB) external onlyRole(RELAYER_ROLE) whenNotPaused nonReentrant {
        Match storage m = matches[matchId];
        require(m.state == MatchState.CREATED, "not joinable");
        require(playerB != address(0) && playerB != m.playerA, "invalid player");

        m.playerB = playerB;
        m.state = MatchState.JOINED;
        arenaToken.safeTransferFrom(playerB, address(this), m.stakeAmount);

        emit MatchJoined(matchId, playerB, m.stakeAmount * 2);
    }

    /// @notice Marks the match as started — the backend now runs the AI battle off-chain.
    function startMatch(bytes32 matchId) external onlyRole(RELAYER_ROLE) whenNotPaused {
        Match storage m = matches[matchId];
        require(m.state == MatchState.JOINED, "not ready");
        m.state = MatchState.STARTED;
        emit MatchStarted(matchId);
    }

    /**
     * @notice Backend submits the verified battle result. Pays the winner
     *         (pool minus commission) and routes the commission to the
     *         treasury, all in the same transaction.
     */
    function settleMatch(bytes32 matchId, address winner) external onlyRole(RELAYER_ROLE) whenNotPaused nonReentrant {
        Match storage m = matches[matchId];
        require(m.state == MatchState.STARTED, "not started");
        require(winner == m.playerA || winner == m.playerB, "winner not in match");

        m.state = MatchState.SETTLED;

        uint256 pool = m.stakeAmount * 2;
        uint256 commission = (pool * commissionBps) / 10_000;
        uint256 payout = pool - commission;

        arenaToken.safeTransfer(winner, payout);
        if (commission > 0) {
            arenaToken.safeTransfer(address(treasury), commission);
            treasury.notifyCommission(commission);
            emit CommissionCollected(matchId, commission);
        }

        emit MatchSettled(matchId, winner, payout, commission);
    }

    /// @notice Refunds stakes for a match that never completed (e.g. opponent no-show, dispute).
    function cancelMatch(bytes32 matchId) external onlyRole(RELAYER_ROLE) whenNotPaused nonReentrant {
        Match storage m = matches[matchId];
        require(m.state == MatchState.CREATED || m.state == MatchState.JOINED || m.state == MatchState.STARTED, "not cancellable");

        MatchState priorState = m.state;
        m.state = MatchState.CANCELLED;

        arenaToken.safeTransfer(m.playerA, m.stakeAmount);
        if (priorState != MatchState.CREATED) {
            arenaToken.safeTransfer(m.playerB, m.stakeAmount);
        }

        emit MatchCancelled(matchId);
    }

    // ── Views ─────────────────────────────────────────────────────────────────

    function getMatch(bytes32 matchId) external view returns (Match memory) {
        return matches[matchId];
    }

    // ── Admin ────────────────────────────────────────────────────────────────

    function setCommissionBps(uint256 bps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(bps <= MAX_COMMISSION_BPS, "commission too high");
        commissionBps = bps;
        emit CommissionBpsUpdated(bps);
    }

    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) { _pause(); }
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) { _unpause(); }
}

contracts/arena/ArenaToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

/**
 * @title  ArenaToken
 *
 * @notice The $ARENA in-game currency for the 0G Chain beta economy.
 *         Fixed supply, minted once at deployment directly to the
 *         ArenaTreasury address. There is no mint function of any kind —
 *         not owner-gated, not role-gated — so the supply cap is enforced
 *         by the absence of the capability, not by a permission check.
 *
 * @dev    Standard OpenZeppelin ERC20 (transfer/transferFrom/balanceOf/
 *         totalSupply/approve/allowance) with no extensions. All economy
 *         logic (rewards, escrow, commissions) lives in the separate
 *         ArenaTreasury / RewardDistributor / ArenaEscrow / ArenaTournament
 *         contracts, which move tokens via standard ERC20 transfers.
 */
contract ArenaToken is ERC20 {
    /// @notice Fixed beta-economy supply: 1,000,000 ARENA (18 decimals).
    uint256 public constant INITIAL_SUPPLY = 1_000_000 * 10 ** 18;

    /**
     * @param treasury Recipient of the entire initial supply. Must be the
     *                 deployed ArenaTreasury contract address.
     */
    constructor(address treasury) ERC20("Arena Token", "ARENA") {
        require(treasury != address(0), "zero treasury");
        _mint(treasury, INITIAL_SUPPLY);
    }
}

contracts/arena/ArenaTournament.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./ArenaTreasury.sol";

/**
 * @title  ArenaTournament
 *
 * @notice Multi-participant entry-fee pool with placement-based prize
 *         distribution, mirroring ArenaEscrow's stake-pool-settle pattern
 *         for 1v1 wagers but for N participants. The prize pool is funded
 *         entirely by entrants' own entry fees (pulled via `transferFrom`,
 *         same sponsored-relayer pattern as ArenaEscrow) — the treasury
 *         only ever *receives* the commission cut here, it never funds the
 *         base prize pool. A separate, treasury-funded "tournament bonus"
 *         (e.g. a platform-seeded top-up) is handled by
 *         RewardDistributor.grantTournamentReward, not by this contract.
 */
contract ArenaTournament is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");

    enum TournamentState { NONE, OPEN, STARTED, SETTLED, CANCELLED }

    struct TournamentInfo {
        uint256 entryFee;
        uint256 maxParticipants;
        TournamentState state;
        address[] participants;
    }

    IERC20 public immutable arenaToken;
    ArenaTreasury public immutable treasury;

    /// @notice Commission taken from the entry-fee pool at settlement, in basis points.
    uint256 public commissionBps = 1000; // 10%
    uint256 public constant MAX_COMMISSION_BPS = 2000;

    mapping(uint256 => TournamentInfo) public tournaments;
    mapping(uint256 => mapping(address => bool)) public isEntrant;

    event TournamentCreated(uint256 indexed tournamentId, uint256 entryFee, uint256 maxParticipants);
    event TournamentEntered(uint256 indexed tournamentId, address indexed player, uint256 participantCount);
    event TournamentStarted(uint256 indexed tournamentId, uint256 participantCount);
    event TournamentRewardGranted(address indexed player, uint256 indexed tournamentId, uint256 rank, uint256 amount);
    event CommissionCollected(uint256 indexed tournamentId, uint256 amount);
    event TournamentCancelled(uint256 indexed tournamentId);
    event CommissionBpsUpdated(uint256 newBps);

    constructor(address admin, address arenaTokenAddress, address treasuryAddress) {
        require(admin != address(0), "zero admin");
        require(arenaTokenAddress != address(0), "zero token");
        require(treasuryAddress != address(0), "zero treasury");
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        arenaToken = IERC20(arenaTokenAddress);
        treasury = ArenaTreasury(treasuryAddress);
    }

    function createTournament(uint256 tournamentId, uint256 entryFee, uint256 maxParticipants) external onlyRole(RELAYER_ROLE) whenNotPaused {
        require(tournaments[tournamentId].state == TournamentState.NONE, "tournament exists");
        require(entryFee > 0, "zero entry fee");
        require(maxParticipants >= 2, "need >= 2 participants");

        TournamentInfo storage t = tournaments[tournamentId];
        t.entryFee = entryFee;
        t.maxParticipants = maxParticipants;
        t.state = TournamentState.OPEN;

        emit TournamentCreated(tournamentId, entryFee, maxParticipants);
    }

    function enterTournament(uint256 tournamentId, address player) external onlyRole(RELAYER_ROLE) whenNotPaused nonReentrant {
        TournamentInfo storage t = tournaments[tournamentId];
        require(t.state == TournamentState.OPEN, "not open");
        require(!isEntrant[tournamentId][player], "already entered");
        require(t.participants.length < t.maxParticipants, "tournament full");

        isEntrant[tournamentId][player] = true;
        t.participants.push(player);
        arenaToken.safeTransferFrom(player, address(this), t.entryFee);

        emit TournamentEntered(tournamentId, player, t.participants.length);
    }

    function startTournament(uint256 tournamentId) external onlyRole(RELAYER_ROLE) whenNotPaused {
        TournamentInfo storage t = tournaments[tournamentId];
        require(t.state == TournamentState.OPEN, "not open");
        require(t.participants.length >= 2, "not enough participants");
        t.state = TournamentState.STARTED;
        emit TournamentStarted(tournamentId, t.participants.length);
    }

    /**
     * @notice Settle the tournament: `winners[i]` receives `prizeBps[i]` of
     *         the entry-fee pool (after commission), in placement order
     *         (winners[0] = 1st place, etc). `sum(prizeBps) + commissionBps`
     *         must not exceed 10,000 (100%); any un-awarded remainder stays
     *         in the contract's balance (recoverable via emergency admin
     *         action if ever needed — not exposed here to keep the settle
     *         path simple and auditable).
     */
    function settleTournament(
        uint256 tournamentId,
        address[] calldata winners,
        uint256[] calldata prizeBps
    ) external onlyRole(RELAYER_ROLE) whenNotPaused nonReentrant {
        TournamentInfo storage t = tournaments[tournamentId];
        require(t.state == TournamentState.STARTED, "not started");
        require(winners.length == prizeBps.length && winners.length > 0, "length mismatch");

        t.state = TournamentState.SETTLED;

        uint256 pool = t.entryFee * t.participants.length;
        uint256 commission = (pool * commissionBps) / 10_000;

        uint256 totalPrizeBps = 0;
        for (uint256 i = 0; i < prizeBps.length; i++) {
            totalPrizeBps += prizeBps[i];
        }
        require(totalPrizeBps + commissionBps <= 10_000, "prize allocation exceeds pool");

        for (uint256 i = 0; i < winners.length; i++) {
            require(isEntrant[tournamentId][winners[i]], "winner not entrant");
            uint256 amount = (pool * prizeBps[i]) / 10_000;
            if (amount > 0) {
                arenaToken.safeTransfer(winners[i], amount);
                emit TournamentRewardGranted(winners[i], tournamentId, i + 1, amount);
            }
        }

        if (commission > 0) {
            arenaToken.safeTransfer(address(treasury), commission);
            treasury.notifyCommission(commission);
            emit CommissionCollected(tournamentId, commission);
        }
    }

    /// @notice Refunds all entrants for a tournament that never started.
    function cancelTournament(uint256 tournamentId) external onlyRole(RELAYER_ROLE) whenNotPaused nonReentrant {
        TournamentInfo storage t = tournaments[tournamentId];
        require(t.state == TournamentState.OPEN, "not cancellable");
        t.state = TournamentState.CANCELLED;

        for (uint256 i = 0; i < t.participants.length; i++) {
            arenaToken.safeTransfer(t.participants[i], t.entryFee);
        }

        emit TournamentCancelled(tournamentId);
    }

    // ── Views ─────────────────────────────────────────────────────────────────

    function getParticipants(uint256 tournamentId) external view returns (address[] memory) {
        return tournaments[tournamentId].participants;
    }

    // ── Admin ────────────────────────────────────────────────────────────────

    function setCommissionBps(uint256 bps) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(bps <= MAX_COMMISSION_BPS, "commission too high");
        commissionBps = bps;
        emit CommissionBpsUpdated(bps);
    }

    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) { _pause(); }
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) { _unpause(); }
}

contracts/arena/ArenaTreasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title  ArenaTreasury
 *
 * @notice Holds the entire $ARENA fixed supply and is the sole source of
 *         every reward paid out in the beta economy. Never mints — only
 *         moves tokens it already holds.
 *
 * Two kinds of contracts are granted SPENDER_ROLE:
 *   - RewardDistributor: calls `distribute()` to pay out Agent Mint,
 *     Training, Daily Login, Referral, Quest, Tournament and Seasonal
 *     rewards from the treasury balance.
 *   - ArenaEscrow / ArenaTournament: after settling a match/tournament and
 *     transferring the commission cut to this contract directly via
 *     `arenaToken.transfer(treasury, commission)`, they call
 *     `notifyCommission()` so the treasury's on-chain accounting (and the
 *     `CommissionCollected` / `TreasuryUpdated` events analytics dashboards
 *     index) stays in sync with the real token balance.
 *
 * @dev    Deployment order breaks the ArenaToken <-> ArenaTreasury circular
 *         dependency: deploy ArenaTreasury first, then ArenaToken(treasury
 *         address), then call `setArenaToken()` once. See
 *         scripts/deploy-arena-economy.ts.
 *
 *         DEFAULT_ADMIN_ROLE should be held by a multisig in production
 *         (see docs/ARENA_TOKEN_0G.md) — it is the only role that can grant
 *         or revoke SPENDER_ROLE or set the token address, so compromising
 *         a single spender contract cannot be used to add new spenders.
 */
contract ArenaTreasury is AccessControl {
    using SafeERC20 for IERC20;

    bytes32 public constant SPENDER_ROLE = keccak256("SPENDER_ROLE");

    IERC20 public arenaToken;
    bool public arenaTokenSet;

    /// @notice Cumulative amount ever paid out via `distribute()` (reward payouts only).
    uint256 public totalRewardsPaid;

    /// @notice Cumulative commission received from escrow/tournament settlements.
    uint256 public totalCommissions;

    event ArenaTokenSet(address indexed token);
    event TreasuryUpdated(uint256 balance, uint256 totalRewardsPaid, uint256 totalCommissions);
    event RewardDistributed(address indexed spender, address indexed to, uint256 amount, string category);
    event CommissionCollected(address indexed spender, uint256 amount);

    constructor(address admin) {
        require(admin != address(0), "zero admin");
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
    }

    /**
     * @notice One-time wiring of the ArenaToken address, called immediately
     *         after ArenaToken is deployed (which mints the fixed supply to
     *         this contract's address). Cannot be changed afterwards.
     */
    function setArenaToken(address token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(!arenaTokenSet, "already set");
        require(token != address(0), "zero token");
        arenaToken = IERC20(token);
        arenaTokenSet = true;
        emit ArenaTokenSet(token);
    }

    /**
     * @notice Pay `amount` ARENA from the treasury to `to`. Only callable by
     *         a granted spender (the RewardDistributor contract).
     */
    function distribute(address to, uint256 amount, string calldata category) external onlyRole(SPENDER_ROLE) {
        require(to != address(0), "zero recipient");
        require(amount > 0, "zero amount");
        totalRewardsPaid += amount;
        arenaToken.safeTransfer(to, amount);
        emit RewardDistributed(msg.sender, to, amount, category);
        emit TreasuryUpdated(balance(), totalRewardsPaid, totalCommissions);
    }

    /**
     * @notice Record a commission that a spender (ArenaEscrow/ArenaTournament)
     *         has already transferred into this contract's own ARENA balance
     *         earlier in the same transaction. This function moves no
     *         tokens — it only updates accounting and emits analytics events.
     */
    function notifyCommission(uint256 amount) external onlyRole(SPENDER_ROLE) {
        require(amount > 0, "zero amount");
        totalCommissions += amount;
        emit CommissionCollected(msg.sender, amount);
        emit TreasuryUpdated(balance(), totalRewardsPaid, totalCommissions);
    }

    // ── Views ─────────────────────────────────────────────────────────────────

    /// @notice Current ARENA balance held by the treasury.
    function balance() public view returns (uint256) {
        return address(arenaToken) == address(0) ? 0 : arenaToken.balanceOf(address(this));
    }

    /// @notice Alias for `balance()` — the "remaining supply" available to distribute.
    function remaining() external view returns (uint256) {
        return balance();
    }

    function distributed() external view returns (uint256) {
        return totalRewardsPaid;
    }
}

contracts/arena/RewardDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./ArenaTreasury.sol";

/**
 * @title  RewardDistributor
 *
 * @notice The only contract allowed to pull ARENA out of the treasury for
 *         player-facing rewards. Every function here is gated to
 *         RELAYER_ROLE — the backend's gas-sponsoring hot wallet — so a
 *         player never signs or pays for these transactions themselves.
 *         This contract never mints; every call is a `treasury.distribute()`
 *         forwarding a transfer of tokens the treasury already holds.
 *
 * @dev    Must be granted `SPENDER_ROLE` on the deployed ArenaTreasury.
 *         Daily login rewards are rate-limited on-chain (one claim per UTC
 *         day per player) so the relayer cannot be tricked/bugged into
 *         paying the same player twice for the same day even if it retries.
 */
contract RewardDistributor is AccessControl, Pausable {
    bytes32 public constant RELAYER_ROLE = keccak256("RELAYER_ROLE");

    ArenaTreasury public immutable treasury;

    /// @notice Fixed reward for successfully minting an Agent NFT.
    uint256 public agentMintReward = 100 * 10 ** 18;

    /// @notice Fixed reward for a daily login claim.
    uint256 public dailyLoginReward = 5 * 10 ** 18;

    /// @dev player => UTC day index (block.timestamp / 1 days) of last daily-login claim.
    mapping(address => uint256) public lastDailyClaimDay;

    // ── Events (minimum event list from the ARENA 0G blueprint) ────────────────
    event AgentRewardGranted(address indexed player, uint256 indexed agentTokenId, uint256 amount);
    event RewardGranted(address indexed player, uint256 amount, string category, string reason);
    event DailyRewardClaimed(address indexed player, uint256 amount, uint256 day);
    event TournamentRewardGranted(address indexed player, uint256 indexed tournamentId, uint256 rank, uint256 amount);
    event ReferralRewardGranted(address indexed referrer, address indexed referee, uint256 amount);

    event AgentMintRewardUpdated(uint256 newAmount);
    event DailyLoginRewardUpdated(uint256 newAmount);

    constructor(address admin, address treasuryAddress) {
        require(admin != address(0), "zero admin");
        require(treasuryAddress != address(0), "zero treasury");
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        treasury = ArenaTreasury(treasuryAddress);
    }

    // ── Agent Mint Flow ──────────────────────────────────────────────────────

    /**
     * @notice Called by the relayer immediately after an Agent NFT mint
     *         succeeds on-chain (see AIArenaINFT.mintAgent). Pays the fixed
     *         Agent Mint reward directly to the player's wallet.
     */
    function grantAgentMintReward(address player, uint256 agentTokenId) external onlyRole(RELAYER_ROLE) whenNotPaused {
        treasury.distribute(player, agentMintReward, "AGENT_MINT");
        emit AgentRewardGranted(player, agentTokenId, agentMintReward);
    }

    // ── Daily Login ──────────────────────────────────────────────────────────

    function grantDailyLoginReward(address player) external onlyRole(RELAYER_ROLE) whenNotPaused {
        uint256 today = block.timestamp / 1 days;
        require(lastDailyClaimDay[player] < today, "already claimed today");
        lastDailyClaimDay[player] = today;
        treasury.distribute(player, dailyLoginReward, "DAILY_LOGIN");
        emit DailyRewardClaimed(player, dailyLoginReward, today);
    }

    // ── Referral ─────────────────────────────────────────────────────────────

    function grantReferralReward(address referrer, address referee, uint256 amount) external onlyRole(RELAYER_ROLE) whenNotPaused {
        require(referrer != address(0) && referee != address(0), "zero address");
        treasury.distribute(referrer, amount, "REFERRAL");
        emit ReferralRewardGranted(referrer, referee, amount);
    }

    // ── Training / Quest / Seasonal (generic categories) ────────────────────

    function grantTrainingReward(address player, uint256 amount, string calldata reason) external onlyRole(RELAYER_ROLE) whenNotPaused {
        treasury.distribute(player, amount, "TRAINING");
        emit RewardGranted(player, amount, "TRAINING", reason);
    }

    function grantQuestReward(address player, uint256 amount, string calldata reason) external onlyRole(RELAYER_ROLE) whenNotPaused {
        treasury.distribute(player, amount, "QUEST");
        emit RewardGranted(player, amount, "QUEST", reason);
    }

    function grantSeasonalReward(address player, uint256 amount, string calldata reason) external onlyRole(RELAYER_ROLE) whenNotPaused {
        treasury.distribute(player, amount, "SEASONAL");
        emit RewardGranted(player, amount, "SEASONAL", reason);
    }

    /**
     * @notice Treasury-funded tournament bonus (e.g. a platform-seeded prize
     *         top-up), distinct from the entry-fee prize pool that
     *         ArenaTournament redistributes among entrants directly.
     */
    function grantTournamentReward(address player, uint256 tournamentId, uint256 rank, uint256 amount) external onlyRole(RELAYER_ROLE) whenNotPaused {
        treasury.distribute(player, amount, "TOURNAMENT");
        emit TournamentRewardGranted(player, tournamentId, rank, amount);
    }

    // ── Admin ────────────────────────────────────────────────────────────────

    function setAgentMintReward(uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        agentMintReward = amount;
        emit AgentMintRewardUpdated(amount);
    }

    function setDailyLoginReward(uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        dailyLoginReward = amount;
        emit DailyLoginRewardUpdated(amount);
    }

    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) { _pause(); }
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) { _unpause(); }
}

